import test from 'node:test';
import assert from 'node:assert/strict';
import {correctProductData} from './product-title-corrections.mjs';
import {MARKETPLACE_FIELD_REVIEWS} from './marketplace-field-reviews.mjs';
const rows=[{id:'mlMLB7502068112',titulo:'Repetidor De Sinal Extensor Internet Wifi 300mbps 2 Antenas',listing:'MLB7502068112'},{id:'NJipazuMXMzOH9YZbxwu',titulo:'Fone De Ouvido Headphone Dapon H02D Bluetooth 5.1 Over-ear 22h Preto',listing:'MLB4587377807'},{id:'rJhe4VyyDiFudQmQmXCV',titulo:'Roçadeira Aparador Grama 2 Baterias Recarregável 21v 750w Profissional Com Acessórios Tcg21cx-2b The Black Tools'}];
test('triagem43 preserva campos operacionais e idempotência sem atingir acessórios',()=>{
 for(const r of rows){const p={...r,preco:'99,99',linkAfiliado:'https://meli.la/preservado',variation_id:'original'},x=correctProductData(p);for(const k of Object.keys(p).filter(k=>k!=='titulo'))assert.equal(x[k],p[k]);assert.deepEqual(correctProductData(x),x);assert.equal(correctProductData({...p,titulo:'Capa para '+r.titulo,comentario:'preservar'}).comentario,'preservar');if(r.listing)assert.equal(correctProductData({...p,link:'https://www.mercadolivre.com.br/p/MLB12345678?wid=MLB9999999999',comentario:'preservar'}).comentario,'preservar');assert.ok(x.titulo.length<=100);}
});
test('Pix-Link não garante velocidade entregue ou modelo desconhecido',()=>{const x=correctProductData(rows[0]);assert.match(x.comentario,/não uma medição de velocidade/);assert.match(x.comentario,/modelo completo e a revisão não estão confirmados/);assert.doesNotMatch(x.pros,/Mesh|5\s*GHz|Gigabit|garant|cobertura total/i);});
test('Dapon só muda título e mantém os fatos da revisão anterior',()=>{const review=MARKETPLACE_FIELD_REVIEWS.get(rows[1].id),p={...rows[1],comentario:review.summary,pros:review.positiveNotes.join('\n'),contras:review.negativeNotes.join('\n')},x=correctProductData(p);assert.doesNotMatch(x.titulo,/22\s*h|35\s*h/i);assert.match(x.titulo,/divergentes/);for(const k of ['comentario','pros','contras'])assert.equal(x[k],p[k]);});
test('TCG21CX não promete conforto profissional ou autonomia',()=>{const x=correctProductData(rows[2]);assert.doesNotMatch(x.titulo,/profissional/i);assert.match(x.comentario,/não informam, por si só/);assert.match(x.comentario,/Os ajustes não comprovam conforto/);assert.doesNotMatch(x.pros,/garant|profissional|mais autonomia|maior conforto|\d+\s*minutos/i);});
